import React from 'react';
import { Composition } from 'remotion';
import { makeTL } from '../lib';
import { OsFcfs } from './Fcfs';
import tFcfs from '../timelines/os-fcfs.json';
import { OsLocks } from './Locks';
import tLocks from '../timelines/os-locks.json';
import { OsManager } from './Manager';
import tManager from '../timelines/os-manager.json';
import { OsProcess } from './Process';
import tProcess from '../timelines/os-process.json';
import { OsRace } from './Race';
import tRace from '../timelines/os-race.json';
import { OsRr } from './Rr';
import tRr from '../timelines/os-rr.json';
import { OsSyscall } from './Syscall';
import tSyscall from '../timelines/os-syscall.json';
import { OsThreads } from './Threads';
import tThreads from '../timelines/os-threads.json';

const comp = (id: string, component: React.FC, t: unknown) => {
  const { TL } = makeTL(t);
  return <Composition key={id} id={id} component={component} durationInFrames={TL.total} fps={TL.fps} width={1920} height={1080} />;
};

export const OsComps: React.FC = () => <>
  {comp('OsFcfs', OsFcfs, tFcfs)}
  {comp('OsLocks', OsLocks, tLocks)}
  {comp('OsManager', OsManager, tManager)}
  {comp('OsProcess', OsProcess, tProcess)}
  {comp('OsRace', OsRace, tRace)}
  {comp('OsRr', OsRr, tRr)}
  {comp('OsSyscall', OsSyscall, tSyscall)}
  {comp('OsThreads', OsThreads, tThreads)}
</>;
